  let fracPart = dot === -1 ? '' : s.slice(dot + 1);
  if (intPart === '') intPart = '0';
  // pad fraction
  while (fracPart.length < 3) fracPart += '0';
  let kept = BigInt(intPart) * 100n + BigInt(fracPart.slice(0, 2));
  let rest = fracPart.slice(2).replace(/0+$/, '');
  let roundUp = false;
  if (rest.length > 0) {
    if (rest[0] > '5') roundUp = true;
    else if (rest[0] < '5') roundUp = false;
    else roundUp = rest.length > 1 ? true : (kept % 2n === 1n);
  }
  if (roundUp) kept += 1n;
  if (neg && kept !== 0n) kept = -kept;
  const abs = kept < 0n ? -kept : kept;
  const units = abs / 100n;
  const cents = (abs % 100n).toString().padStart(2, '0');
  return (kept < 0n ? '-' : '') + units.toString() + '.' + cents;
}

