function solve(input) {
  let s = String(input).trim();
  let neg = false;
  if (s[0] === '+' || s[0] === '-') { neg = s[0] === '-'; s = s.slice(1); }

  // Handle exponent notation by expanding into plain decimal form
  const eIdx = s.search(/[eE]/);
  if (eIdx >= 0) {
    let mant = s.slice(0, eIdx);
    let exp = parseInt(s.slice(eIdx + 1), 10);
    let dot = mant.indexOf('.');
    let digits = mant.replace('.', '');
    let pointPos = (dot < 0 ? mant.length : dot) + exp;
    if (pointPos <= 0) { s = '0.' + '0'.repeat(-pointPos) + digits; }
    else if (pointPos >= digits.length) { s = digits + '0'.repeat(pointPos - digits.length); }
    else { s = digits.slice(0, pointPos) + '.' + digits.slice(pointPos); }
  }

  let dot = s.indexOf('.');
  let intPart = dot >= 0 ? s.slice(0, dot) : s;
  let frac = dot >= 0 ? s.slice(dot + 1) : '';
  if (intPart === '' || intPart === '+') intPart = '0';
  intPart = intPart.replace(/^0+(?=\d)/, '');
  while (frac.length < 3) frac += '0';

  const keep = frac.slice(0, 2);
  const rest = frac.slice(2);

  let scaled = BigInt(intPart) * 100n + BigInt(keep === '' ? '0' : keep);

  // Compare rest (as fraction of 1) with 0.5: 1 greater, 0 tie, -1 less
  let cmp = -1;
  let i = 0;
  while (i < rest.length && rest[i] === '0') i++;
  if (i < rest.length) {
    if (rest[i] > '5') cmp = 1;
    else if (rest[i] < '5') cmp = -1;
    else {
      cmp = 0;
      for (let j = i + 1; j < rest.length; j++) {
        if (rest[j] !== '0') { cmp = 1; break; }
      }
    }
  }

  let roundUp = false;
  if (cmp > 0) roundUp = true;
  else if (cmp === 0 && scaled % 2n === 1n) roundUp = true;
  if (roundUp) scaled += 1n;

  let str = scaled.toString();
  let out;
  if (str.length <= 2) out = '0.' + str.padStart(2, '0');
  else out = str.slice(0, -2) + '.' + str.slice(-2);

  if (scaled === 0n) neg = false;
  return (neg ? '-' : '') + out;
